//! Internal cache/stream payloads, never synchronized or regenerated by admission.
use super::UnifiedPhysicsRuntime;
use crate::engine::file_physics_output_admission::{self as f, Budget, Error, Problem};

pub(super) mod native_records;

impl UnifiedPhysicsRuntime {
    pub(in crate::engine) fn validate_file_observations(
        &self,
        b: &mut Budget,
        events: &[crate::gameplay_event::GameplayEvent],
        world: &crate::world::World,
    ) -> Result<(), Error> {
        let config = self.physics.config();
        b.work(events.len())?;
        b.work(self.contacts.terrain_events.len())?;
        for (i, row) in self.contacts.terrain_events.iter().enumerate() {
            let entity = crate::entity::Entity {
                id: row.actor[0],
                generation: row.actor[1],
            };
            f::require(
                world
                    .generation_at_index(entity.id as usize)
                    .is_some_and(|g| {
                        entity.generation <= g
                            && (world.is_current_entity(entity)
                                || entity.generation != g
                                || g == u32::MAX)
                    }),
                "terrain_events",
                "actor_history",
                i,
                Problem::Reference,
            )?;
        }
        for (i, event) in events
            .iter()
            .enumerate()
            .filter(|(_, e)| e.kind == crate::gameplay_event::GAMEPLAY_EVENT_TERRAIN_IMPACT)
        {
            let row = self
                .contacts
                .terrain_events
                .get(event.payload_bits as usize);
            f::require(
                row.is_some_and(|r| {
                    r.actor == [event.actor_id, event.actor_generation]
                        && event.source_id == u32::MAX
                        && event.source_generation == 0
                        && event.token_id == r.terrain[0]
                        && event.flags == r.flags
                }),
                "terrain_events",
                "event_reference",
                i,
                Problem::Graph,
            )?;
        }
        self.lifecycle
            .validate_file_observations(config.max_events, b)?;
        self.contacts
            .validate_file_observations(config.max_events, b)?;
        b.vector(&self.gameplay_collision_pairs)?;
        b.work(
            self.gameplay_collision_pairs
                .len()
                .checked_mul(4)
                .ok_or(Error::WorkLimit)?,
        )?;
        let mut previous = None;
        for (i, pair) in self.gameplay_collision_pairs.iter().enumerate() {
            let key = (
                (pair.a.id, pair.a.generation),
                (pair.b.id, pair.b.generation),
            );
            f::require(
                key.0 < key.1 && previous.is_none_or(|p| p < key),
                "runtime_gameplay_pairs",
                "order",
                i,
                Problem::Order,
            )?;
            previous = Some(key);
        }
        native_records::queries(self, b)?;
        native_records::joint_events(&self.native_joint_events, config.max_events, b)?;
        self.joint_stream
            .validate_file_observations(config.max_events, b)?;
        self.statistics
            .validate_file_observations(config.max_bodies, b)
    }
}
